constexpr lv_image_dsc_t Make_fish_preview() {
    lv_image_dsc_t d{};
    d.header.magic = LV_IMAGE_HEADER_MAGIC;
    d.header.cf = LV_COLOR_FORMAT_I4;
    d.header.w = 80; d.header.h = 44; d.header.stride = 40;
    d.data_size = sizeof(fish_preview_pixels); d.data = fish_preview_pixels;
    return d;
}
constexpr auto fish_preview_image = Make_fish_preview();
